    "id": "EX800",
    "number": 800,
    "name": "El Reloj de Pases: Conectar 5 Pases Seguidos sin que el Balón se Detenga",
    "category": "13. Fútbol Base",
    "subcategory": "Iniciación al Pase y Control Divertido",
    "objetivoPrincipal": "Promover el desarrollo motriz y la pasión por el fútbol a través de superficie del interior del pie, control de planta y pase cooperativo, en un entorno seguro y formativo.",
    "objetivoTecnico": "Contacto inicial y familiarización con todas las superficies del pie, controles suaves con la suela y golpeos divertidos.",
    "objetivoTatico": "Aprender a compartir el balón con los compañeros, reconocer el espacio libre y disfrutar tanto atacando como defendiendo.",
    "edad": "9–11 años",
    "nivel": "Principiante",
    "jugadoresMin": 4,
    "jugadoresMax": 12,
    "jugadoresLabel": "6–10",
